const std = @import("std");
const net = std.net;
const mem = std.mem;
const http = std.http;
const fs = std.fs;
const json = std.json;
const process = std.process;

const PORT: u16 = 5000;
const MAX_HEADER_SIZE: usize = 64 * 1024;
const MAX_BODY_SIZE: usize = 10 * 1024 * 1024;
const MAX_TOKENS: u32 = 100000;
const MAX_CONNECTIONS: u32 = 256;
const INKO_AGENT_PATH = "agents/azure_openai_agent";

var active_conn_count: u32 = 0;
var active_conn_mutex = std.Thread.Mutex{};

pub fn main() !void {
    std.log.info("port={d} max_tokens={d} max_connections={d}", .{ PORT, MAX_TOKENS, MAX_CONNECTIONS });

    const address = try net.Address.parseIp("0.0.0.0", PORT);
    var server = try address.listen(.{ .reuse_address = true });
    defer server.deinit();

    std.log.info("listening", .{});

    while (true) {
        const conn = server.accept() catch |err| {
            std.log.err("accept: {}", .{err});
            continue;
        };

        active_conn_mutex.lock();
        if (active_conn_count >= MAX_CONNECTIONS) {
            active_conn_mutex.unlock();
            conn.stream.writeAll(
                "HTTP/1.1 429 Too Many Requests\r\nContent-Type: application/json\r\nContent-Length: 29\r\nConnection: close\r\n\r\n{\"error\":\"Too Many Requests\"}",
            ) catch {};
            conn.stream.close();
            continue;
        }
        active_conn_count += 1;
        active_conn_mutex.unlock();

        const thread = std.Thread.spawn(.{}, handleConnection, .{conn}) catch |err| {
            std.log.err("thread: {}", .{err});
            activeConnDecrement();
            conn.stream.close();
            continue;
        };
        thread.detach();
    }
}

fn activeConnDecrement() void {
    active_conn_mutex.lock();
    defer active_conn_mutex.unlock();
    if (active_conn_count > 0) {
        active_conn_count -= 1;
    }
}

fn handleConnection(conn: net.Server.Connection) void {
    defer {
        activeConnDecrement();
        conn.stream.close();
    }

    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    handleRequest(allocator, conn.stream) catch |err| {
        std.log.err("handler: {}", .{err});
        sendError(conn.stream, 500) catch {};
    };
}

fn handleRequest(allocator: mem.Allocator, stream: net.Stream) !void {
    const hdr_buf = try allocator.alloc(u8, MAX_HEADER_SIZE);
    defer allocator.free(hdr_buf);

    var hdr_total: usize = 0;
    var sep_pos: usize = 0;
    var found_sep = false;

    while (hdr_total < MAX_HEADER_SIZE) {
        const n = stream.read(hdr_buf[hdr_total..]) catch {
            try sendError(stream, 400);
            return;
        };
        if (n == 0) {
            if (hdr_total > 0) try sendError(stream, 400);
            return;
        }
        hdr_total += n;
        if (mem.indexOf(u8, hdr_buf[0..hdr_total], "\r\n\r\n")) |pos| {
            sep_pos = pos;
            found_sep = true;
            break;
        }
    }

    if (!found_sep) {
        try sendError(stream, 431);
        return;
    }

    const headers_raw = hdr_buf[0..sep_pos];
    const after_sep = hdr_buf[sep_pos + 4 .. hdr_total];

    const line_end = mem.indexOf(u8, headers_raw, "\r\n") orelse {
        try sendError(stream, 400);
        return;
    };

    var parts = mem.split(u8, headers_raw[0..line_end], " ");
    const method = parts.next() orelse {
        try sendError(stream, 400);
        return;
    };
    const raw_path = parts.next() orelse {
        try sendError(stream, 400);
        return;
    };
    const version = parts.next() orelse {
        try sendError(stream, 400);
        return;
    };

    if (!mem.startsWith(u8, version, "HTTP/")) {
        try sendError(stream, 400);
        return;
    }

    const path = if (mem.indexOf(u8, raw_path, "?")) |q| raw_path[0..q] else raw_path;

    var content_length: ?usize = null;
    var cl_invalid = false;
    var chunked = false;

    var hlines = mem.split(u8, headers_raw[line_end + 2 ..], "\r\n");
    while (hlines.next()) |line| {
        if (line.len == 0) continue;
        const colon = mem.indexOf(u8, line, ":") orelse continue;
        const name = line[0..colon];
        const value = mem.trim(u8, line[colon + 1 ..], " \t");

        var low: [64]u8 = undefined;
        if (name.len > low.len) continue;
        const lname = std.ascii.lowerString(low[0..name.len], name);

        if (mem.eql(u8, lname, "content-length")) {
            content_length = std.fmt.parseInt(usize, value, 10) catch {
                cl_invalid = true;
                break;
            };
        } else if (mem.eql(u8, lname, "transfer-encoding")) {
            var low2: [64]u8 = undefined;
            const lval_len = @min(value.len, low2.len);
            const lval = std.ascii.lowerString(low2[0..lval_len], value[0..lval_len]);
            if (mem.indexOf(u8, lval, "chunked") != null) chunked = true;
        }
    }

    if (cl_invalid) {
        try sendError(stream, 400);
        return;
    }
    if (chunked) {
        try sendError(stream, 501);
        return;
    }

    const needs_body = !mem.eql(u8, method, "GET") and
        !mem.eql(u8, method, "HEAD") and
        !mem.eql(u8, method, "OPTIONS");

    var body_alloc: ?[]u8 = null;
    defer {
        if (body_alloc) |b| allocator.free(b);
    }

    const body: []const u8 = blk: {
        if (!needs_body) break :blk "";

        const cl = content_length orelse {
            try sendError(stream, 411);
            return;
        };
        if (cl == 0) break :blk "";
        if (cl > MAX_BODY_SIZE) {
            try sendError(stream, 413);
            return;
        }
        if (cl <= after_sep.len) break :blk after_sep[0..cl];

        const buf = try allocator.alloc(u8, cl);
        body_alloc = buf;
        @memcpy(buf[0..after_sep.len], after_sep);
        _ = try stream.readAll(buf[after_sep.len..]);
        break :blk buf;
    };

    try routeRequest(allocator, stream, method, path, body);
}

fn routeRequest(
    allocator: mem.Allocator,
    stream: net.Stream,
    method: []const u8,
    path: []const u8,
    body: []const u8,
) !void {
    if (mem.eql(u8, path, "/")) {
        if (mem.eql(u8, method, "GET")) {
            try serveFile(stream, "index.html", "text/html; charset=utf-8", "no-cache");
        } else if (mem.eql(u8, method, "OPTIONS")) {
            try sendOptions(stream);
        } else {
            try sendError(stream, 405);
        }
    } else if (mem.eql(u8, path, "/api/chat")) {
        if (mem.eql(u8, method, "POST")) {
            try handleChat(allocator, stream, body);
        } else if (mem.eql(u8, method, "OPTIONS")) {
            try sendOptions(stream);
        } else {
            try sendError(stream, 405);
        }
    } else if (mem.eql(u8, path, "/sw.js")) {
        if (mem.eql(u8, method, "GET")) {
            try serveFile(stream, "sw.js", "application/javascript", "public, max-age=3600");
        } else if (mem.eql(u8, method, "OPTIONS")) {
            try sendOptions(stream);
        } else {
            try sendError(stream, 405);
        }
    } else if (mem.eql(u8, path, "/health")) {
        if (mem.eql(u8, method, "GET")) {
            try sendHealth(stream);
        } else if (mem.eql(u8, method, "OPTIONS")) {
            try sendOptions(stream);
        } else {
            try sendError(stream, 405);
        }
    } else if (mem.eql(u8, method, "OPTIONS")) {
        try sendOptions(stream);
    } else {
        try sendError(stream, 404);
    }
}

fn serveFile(stream: net.Stream, file_path: []const u8, content_type: []const u8, cache: []const u8) !void {
    const file = fs.cwd().openFile(file_path, .{}) catch |err| switch (err) {
        error.FileNotFound, error.BadPathName => return sendError(stream, 404),
        error.AccessDenied => return sendError(stream, 403),
        else => return sendError(stream, 500),
    };
    defer file.close();

    const stat = file.stat() catch return sendError(stream, 500);
    const size = stat.size;

    var hdr: [512]u8 = undefined;
    const hdr_str = try std.fmt.bufPrint(
        &hdr,
        "HTTP/1.1 200 OK\r\nContent-Type: {s}\r\nContent-Length: {d}\r\nCache-Control: {s}\r\nAccess-Control-Allow-Origin: *\r\nConnection: close\r\n\r\n",
        .{ content_type, size, cache },
    );
    try stream.writeAll(hdr_str);

    var file_buf: [8192]u8 = undefined;
    while (true) {
        const n = file.read(&file_buf) catch break;
        if (n == 0) break;
        stream.writeAll(file_buf[0..n]) catch break;
    }
}

fn sendHealth(stream: net.Stream) !void {
    var body_buf: [128]u8 = undefined;
    const body = try std.fmt.bufPrint(
        &body_buf,
        "{{\"status\":\"ok\",\"backend\":\"zig\",\"max_tokens\":{d}}}",
        .{MAX_TOKENS},
    );
    try sendJson(stream, 200, body);
}

fn handleChat(allocator: mem.Allocator, stream: net.Stream, body: []const u8) !void {
    const model_id = process.getEnvVarOwned(allocator, "AZURE_MODEL") catch
        try allocator.dupe(u8, "gpt-5.3-chat");
    defer allocator.free(model_id);

    const messages_json = extractMessages(allocator, body) catch {
        const err_resp = try std.fmt.allocPrint(allocator, "{{\"response\":\"Invalid request body.\",\"model\":\"{s}\",\"backend\":\"zig\"}}", .{model_id});
        defer allocator.free(err_resp);
        return sendJson(stream, 400, err_resp);
    };
    defer allocator.free(messages_json);

    const response_text = blk: {
        if (tryInkoAgent(allocator, messages_json)) |text| {
            break :blk text;
        } else |_| {
            break :blk try callAzureOpenAI(allocator, body, model_id);
        }
    };
    defer allocator.free(response_text);

    var resp_json = std.ArrayList(u8).init(allocator);
    defer resp_json.deinit();
    try json.stringify(
        .{ .response = response_text, .model = model_id, .backend = "zig" },
        .{},
        resp_json.writer(),
    );

    try sendJson(stream, 200, resp_json.items);
}

fn tryInkoAgent(allocator: mem.Allocator, input: []const u8) ![]u8 {
    fs.cwd().access(INKO_AGENT_PATH, .{}) catch return error.AgentNotFound;

    var child = std.process.Child.init(&[_][]const u8{INKO_AGENT_PATH}, allocator);
    child.stdin_behavior = .Pipe;
    child.stdout_behavior = .Pipe;
    child.stderr_behavior = .Inherit;

    try child.spawn();

    errdefer {
        _ = child.kill() catch {};
        _ = child.wait() catch {};
    }

    try child.stdin.?.writeAll(input);
    child.stdin.?.close();
    child.stdin = null;

    const stdout = try child.stdout.?.readToEndAlloc(allocator, MAX_BODY_SIZE);
    errdefer allocator.free(stdout);

    const term = try child.wait();
    switch (term) {
        .Exited => |code| {
            if (code != 0) {
                allocator.free(stdout);
                return error.AgentNonZeroExit;
            }
        },
        else => {
            allocator.free(stdout);
            return error.AgentCrashed;
        },
    }

    return stdout;
}

fn callAzureOpenAI(allocator: mem.Allocator, body: []const u8, model_id: []const u8) ![]u8 {
    const api_key = process.getEnvVarOwned(allocator, "AZURE_API_KEY") catch {
        return try allocator.dupe(u8, "AZURE_API_KEY is not configured.");
    };
    defer allocator.free(api_key);

    const endpoint = process.getEnvVarOwned(allocator, "AZURE_EXISTING_AIPROJECT_ENDPOINT") catch
        try allocator.dupe(u8, "");
    defer allocator.free(endpoint);

    const messages_json = extractMessages(allocator, body) catch |err| {
        return try std.fmt.allocPrint(allocator, "Invalid request: {}", .{err});
    };
    defer allocator.free(messages_json);

    std.log.info("POST {s}/openai/v1/responses model={s}", .{ endpoint, model_id });

    return callResponses(allocator, endpoint, api_key, messages_json, model_id, MAX_TOKENS) catch |err| {
        return try std.fmt.allocPrint(allocator, "API request failed: {}", .{err});
    };
}

fn extractMessages(allocator: mem.Allocator, body: []const u8) ![]u8 {
    const parsed = try json.parseFromSlice(json.Value, allocator, body, .{});
    defer parsed.deinit();

    if (parsed.value != .object) return error.InvalidBody;
    const msgs = parsed.value.object.get("messages") orelse return error.MissingMessages;
    if (msgs != .array) return error.InvalidMessages;

    for (msgs.array.items) |item| {
        if (item != .object) return error.InvalidMessages;
        _ = item.object.get("role") orelse return error.InvalidMessages;
        _ = item.object.get("content") orelse return error.InvalidMessages;
    }

    var out = std.ArrayList(u8).init(allocator);
    errdefer out.deinit();
    try json.stringify(msgs, .{}, out.writer());
    return out.toOwnedSlice();
}

fn callResponses(
    allocator: mem.Allocator,
    endpoint: []const u8,
    api_key: []const u8,
    messages_json: []const u8,
    model_id: []const u8,
    max_tokens: u32,
) ![]u8 {
    var http_client = http.Client{ .allocator = allocator };
    defer http_client.deinit();

    const norm = if (mem.endsWith(u8, endpoint, "/")) endpoint[0 .. endpoint.len - 1] else endpoint;
    const api_url = try std.fmt.allocPrint(allocator, "{s}/openai/v1/responses", .{norm});
    defer allocator.free(api_url);

    const req_body = try buildResponsesBody(allocator, messages_json, model_id, max_tokens);
    defer allocator.free(req_body);

    const uri = try std.Uri.parse(api_url);
    const extra_headers = &[_]http.Header{
        .{ .name = "content-type", .value = "application/json" },
        .{ .name = "accept", .value = "application/json" },
        .{ .name = "api-key", .value = api_key },
    };
    const server_header_buffer = try allocator.alloc(u8, MAX_HEADER_SIZE);
    defer allocator.free(server_header_buffer);

    std.log.info("POST {s}", .{api_url});

    var req = try http_client.open(.POST, uri, .{
        .server_header_buffer = server_header_buffer,
        .extra_headers = extra_headers,
    });
    defer req.deinit();

    req.transfer_encoding = .{ .content_length = req_body.len };
    try req.send();
    try req.writer().writeAll(req_body);
    try req.finish();
    try req.wait();

    const status_int = @intFromEnum(req.response.status);
    std.log.info("status={d}", .{status_int});

    const resp_body = try req.reader().readAllAlloc(allocator, MAX_BODY_SIZE);
    errdefer allocator.free(resp_body);

    if (status_int < 200 or status_int >= 300) {
        const msg = try extractErrorMessage(allocator, resp_body);
        defer allocator.free(msg);
        return try std.fmt.allocPrint(allocator, "HTTP {d} from upstream API: {s}", .{ status_int, msg });
    }

    return extractOutputText(allocator, resp_body);
}

fn buildResponsesBody(
    allocator: mem.Allocator,
    input_json: []const u8,
    model_id: []const u8,
    max_tokens: u32,
) ![]u8 {
    var out = std.ArrayList(u8).init(allocator);
    errdefer out.deinit();
    const w = out.writer();
    try w.writeAll("{\"model\":");
    try json.stringify(model_id, .{}, w);
    try w.writeAll(",\"input\":");
    try w.writeAll(input_json);
    try w.print(",\"max_output_tokens\":{d}}}", .{max_tokens});
    return out.toOwnedSlice();
}

fn extractErrorMessage(allocator: mem.Allocator, body: []const u8) ![]u8 {
    const parsed = json.parseFromSlice(json.Value, allocator, body, .{}) catch {
        return try allocator.dupe(u8, body);
    };
    defer parsed.deinit();

    if (parsed.value != .object) {
        return try allocator.dupe(u8, body);
    }

    if (parsed.value.object.get("error_description")) |value| {
        if (value == .string and value.string.len > 0) {
            return try allocator.dupe(u8, value.string);
        }
    }
    if (parsed.value.object.get("message")) |value| {
        if (value == .string and value.string.len > 0) {
            return try allocator.dupe(u8, value.string);
        }
    }
    if (parsed.value.object.get("error")) |err_val| {
        if (err_val == .string and err_val.string.len > 0) {
            return try allocator.dupe(u8, err_val.string);
        }
        if (err_val == .object) {
            if (err_val.object.get("message")) |msg| {
                if (msg == .string and msg.string.len > 0) {
                    return try allocator.dupe(u8, msg.string);
                }
            }
        }
    }

    return try allocator.dupe(u8, body);
}

fn appendOutputValue(buf: *std.ArrayList(u8), value: json.Value) !void {
    switch (value) {
        .string => |text| {
            if (text.len > 0) try buf.appendSlice(text);
        },
        .array => |items| {
            for (items.items) |item| {
                try appendOutputValue(buf, item);
            }
        },
        .object => |obj| {
            if (obj.get("text")) |text| try appendOutputValue(buf, text);
            if (obj.get("value")) |text| try appendOutputValue(buf, text);
            if (obj.get("content")) |content| try appendOutputValue(buf, content);
        },
        else => {},
    }
}

fn extractOutputText(allocator: mem.Allocator, body: []const u8) ![]u8 {
    const parsed = json.parseFromSlice(json.Value, allocator, body, .{}) catch {
        return try allocator.dupe(u8, "Failed to parse API response.");
    };
    defer parsed.deinit();

    if (parsed.value != .object) {
        return try allocator.dupe(u8, "The responses response is not a JSON object.");
    }

    if (parsed.value.object.get("output_text")) |ot| {
        if (ot == .string and ot.string.len > 0) {
            return try allocator.dupe(u8, ot.string);
        }
    }

    if (parsed.value.object.get("output_text")) |ot| {
        var direct = std.ArrayList(u8).init(allocator);
        errdefer direct.deinit();
        try appendOutputValue(&direct, ot);
        if (direct.items.len > 0) {
            return direct.toOwnedSlice();
        }
    }

    if (parsed.value.object.get("output")) |output| {
        var buf = std.ArrayList(u8).init(allocator);
        errdefer buf.deinit();
        try appendOutputValue(&buf, output);
        if (buf.items.len > 0) return buf.toOwnedSlice();
        buf.deinit();
        return try allocator.dupe(u8, "No text output in response.");
    }

    if (parsed.value.object.get("error")) |err_val| {
        var msg = std.ArrayList(u8).init(allocator);
        defer msg.deinit();
        try json.stringify(err_val, .{}, msg.writer());
        return try std.fmt.allocPrint(allocator, "API Error: {s}", .{msg.items});
    }

    return try allocator.dupe(u8, "Could not extract response from API.");
}

fn sendJson(stream: net.Stream, status: u16, body: []const u8) !void {
    const status_text: []const u8 = switch (status) {
        200 => "OK",
        201 => "Created",
        400 => "Bad Request",
        404 => "Not Found",
        500 => "Internal Server Error",
        else => "OK",
    };
    var hdr: [512]u8 = undefined;
    const hdr_str = try std.fmt.bufPrint(
        &hdr,
        "HTTP/1.1 {d} {s}\r\nContent-Type: application/json\r\nContent-Length: {d}\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type\r\nConnection: close\r\n\r\n",
        .{ status, status_text, body.len },
    );
    try stream.writeAll(hdr_str);
    try stream.writeAll(body);
}

fn sendError(stream: net.Stream, status: u16) !void {
    const body: []const u8 = switch (status) {
        400 => "{\"error\":\"Bad Request\"}",
        403 => "{\"error\":\"Forbidden\"}",
        404 => "{\"error\":\"Not Found\"}",
        405 => "{\"error\":\"Method Not Allowed\"}",
        411 => "{\"error\":\"Length Required\"}",
        413 => "{\"error\":\"Payload Too Large\"}",
        429 => "{\"error\":\"Too Many Requests\"}",
        431 => "{\"error\":\"Request Header Fields Too Large\"}",
        500 => "{\"error\":\"Internal Server Error\"}",
        501 => "{\"error\":\"Not Implemented\"}",
        else => "{\"error\":\"Error\"}",
    };
    const status_text: []const u8 = switch (status) {
        400 => "Bad Request",
        403 => "Forbidden",
        404 => "Not Found",
        405 => "Method Not Allowed",
        411 => "Length Required",
        413 => "Payload Too Large",
        429 => "Too Many Requests",
        431 => "Request Header Fields Too Large",
        500 => "Internal Server Error",
        501 => "Not Implemented",
        else => "Error",
    };
    var hdr: [512]u8 = undefined;
    const hdr_str = std.fmt.bufPrint(
        &hdr,
        "HTTP/1.1 {d} {s}\r\nContent-Type: application/json\r\nContent-Length: {d}\r\nAccess-Control-Allow-Origin: *\r\nConnection: close\r\n\r\n",
        .{ status, status_text, body.len },
    ) catch return;
    try stream.writeAll(hdr_str);
    try stream.writeAll(body);
}

fn sendOptions(stream: net.Stream) !void {
    try stream.writeAll(
        "HTTP/1.1 204 No Content\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
    );
}





