    };
}

fn extractMessages(allocator: mem.Allocator, body: []const u8) ![]u8 {
    const parsed = try json.parseFromSlice(json.Value, allocator, body, .{});
    defer parsed.deinit();

    if (parsed.value != .object) return error.InvalidBody;
    const msgs = parsed.value.object.get("messages") orelse return error.MissingMessages;
    if (msgs != .array) return error.InvalidMessages;

    for (msgs.array.items) |item| {
        if (item != .object) return error.InvalidMessages;
        _ = item.object.get("role") orelse return error.InvalidMessages;
        _ = item.object.get("content") orelse return error.InvalidMessages;
    }

    var out = std.ArrayList(u8).init(allocator);
    errdefer out.deinit();
    try json.stringify(msgs, .{}, out.writer());
    return out.toOwnedSlice();
}

fn callResponses(
    allocator: mem.Allocator,
    endpoint: []const u8,
    api_key: []const u8,
    messages_json: []const u8,
    model_id: []const u8,
    max_tokens: u32,
) ![]u8 {
    var http_client = http.Client{ .allocator = allocator };
    defer http_client.deinit();

    const norm = if (mem.endsWith(u8, endpoint, "/")) endpoint[0 .. endpoint.len - 1] else endpoint;
    const api_url = try std.fmt.allocPrint(allocator, "{s}/openai/v1/responses", .{norm});
    defer allocator.free(api_url);

    const req_body = try buildResponsesBody(allocator, messages_json, model_id, max_tokens);
    defer allocator.free(req_body);

    const uri = try std.Uri.parse(api_url);
    const extra_headers = &[_]http.Header{
        .{ .name = "content-type", .value = "application/json" },
        .{ .name = "accept", .value = "application/json" },
        .{ .name = "api-key", .value = api_key },
    };
    const server_header_buffer = try allocator.alloc(u8, MAX_HEADER_SIZE);
    defer allocator.free(server_header_buffer);

    std.log.info("POST {s}", .{api_url});

    var req = try http_client.open(.POST, uri, .{
        .server_header_buffer = server_header_buffer,
        .extra_headers = extra_headers,
    });
    defer req.deinit();

    req.transfer_encoding = .{ .content_length = req_body.len };
    try req.send();
    try req.writer().writeAll(req_body);
    try req.finish();
    try req.wait();

    const status_int = @intFromEnum(req.response.status);
    std.log.info("status={d}", .{status_int});

    const resp_body = try req.reader().readAllAlloc(allocator, MAX_BODY_SIZE);
    errdefer allocator.free(resp_body);

    if (status_int < 200 or status_int >= 300) {
        const msg = try extractErrorMessage(allocator, resp_body);
        defer allocator.free(msg);
        return try std.fmt.allocPrint(allocator, "HTTP {d} from upstream API: {s}", .{ status_int, msg });
    }

    return extractOutputText(allocator, resp_body);
}

fn buildResponsesBody(
    allocator: mem.Allocator,
    input_json: []const u8,
    model_id: []const u8,
    max_tokens: u32,
) ![]u8 {
    var out = std.ArrayList(u8).init(allocator);
    errdefer out.deinit();
    const w = out.writer();
    try w.writeAll("{\"model\":");
    try json.stringify(model_id, .{}, w);
    try w.writeAll(",\"input\":");
    try w.writeAll(input_json);
    try w.print(",\"max_output_tokens\":{d}}}", .{max_tokens});
    return out.toOwnedSlice();
}

fn extractErrorMessage(allocator: mem.Allocator, body: []const u8) ![]u8 {
    const parsed = json.parseFromSlice(json.Value, allocator, body, .{}) catch {
        return try allocator.dupe(u8, body);
    };
    defer parsed.deinit();

    if (parsed.value != .object) {
        return try allocator.dupe(u8, body);
    }

    if (parsed.value.object.get("error_description")) |value| {
        if (value == .string and value.string.len > 0) {
            return try allocator.dupe(u8, value.string);
        }
    }
    if (parsed.value.object.get("message")) |value| {
        if (value == .string and value.string.len > 0) {
            return try allocator.dupe(u8, value.string);
        }
    }
    if (parsed.value.object.get("error")) |err_val| {
        if (err_val == .string and err_val.string.len > 0) {
            return try allocator.dupe(u8, err_val.string);
        }
        if (err_val == .object) {
            if (err_val.object.get("message")) |msg| {
                if (msg == .string and msg.string.len > 0) {
                    return try allocator.dupe(u8, msg.string);
                }
            }
        }
    }

    return try allocator.dupe(u8, body);
}

fn appendOutputValue(buf: *std.ArrayList(u8), value: json.Value) !void {
    switch (value) {
        .string => |text| {
            if (text.len > 0) try buf.appendSlice(text);
        },
        .array => |items| {
            for (items.items) |item| {
                try appendOutputValue(buf, item);
            }
        },
        .object => |obj| {
            if (obj.get("text")) |text| try appendOutputValue(buf, text);
            if (obj.get("value")) |text| try appendOutputValue(buf, text);
            if (obj.get("content")) |content| try appendOutputValue(buf, content);
        },
        else => {},
    }
}

fn extractOutputText(allocator: mem.Allocator, body: []const u8) ![]u8 {
    const parsed = json.parseFromSlice(json.Value, allocator, body, .{}) catch {
        return try allocator.dupe(u8, "Failed to parse API response.");
    };
    defer parsed.deinit();

    if (parsed.value != .object) {
        return try allocator.dupe(u8, "The responses response is not a JSON object.");
    }

    if (parsed.value.object.get("output_text")) |ot| {
        if (ot == .string and ot.string.len > 0) {
            return try allocator.dupe(u8, ot.string);
        }
    }

    if (parsed.value.object.get("output_text")) |ot| {
        var direct = std.ArrayList(u8).init(allocator);
        errdefer direct.deinit();
        try appendOutputValue(&direct, ot);
        if (direct.items.len > 0) {
            return direct.toOwnedSlice();
        }
    }

    if (parsed.value.object.get("output")) |output| {
        var buf = std.ArrayList(u8).init(allocator);
        errdefer buf.deinit();
        try appendOutputValue(&buf, output);
        if (buf.items.len > 0) return buf.toOwnedSlice();
        buf.deinit();
        return try allocator.dupe(u8, "No text output in response.");
    }

    if (parsed.value.object.get("error")) |err_val| {
        var msg = std.ArrayList(u8).init(allocator);
        defer msg.deinit();
        try json.stringify(err_val, .{}, msg.writer());
        return try std.fmt.allocPrint(allocator, "API Error: {s}", .{msg.items});
    }

    return try allocator.dupe(u8, "Could not extract response from API.");
}

fn sendJson(stream: net.Stream, status: u16, body: []const u8) !void {
    const status_text: []const u8 = switch (status) {
        200 => "OK",
        201 => "Created",
        400 => "Bad Request",
        404 => "Not Found",
        500 => "Internal Server Error",
        else => "OK",
    };
    var hdr: [512]u8 = undefined;
    const hdr_str = try std.fmt.bufPrint(
        &hdr,
        "HTTP/1.1 {d} {s}\r\nContent-Type: application/json\r\nContent-Length: {d}\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type\r\nConnection: close\r\n\r\n",
        .{ status, status_text, body.len },
    );
    try stream.writeAll(hdr_str);
    try stream.writeAll(body);
}

