import std.env
import std.io (Buffer)
import std.json (Json)
import std.map (Map)
import std.stdio (Stderr, Stdout, Stdin)
import std.string (StringBuffer)
import std.sys (Command, Stream)

let MAX_TOKENS = 100000
let MAX_INPUT_BYTES = 10 * 1024 * 1024
let DEFAULT_ENDPOINT = ''
let DEFAULT_AGENT_ID = 'bibi:2'

fn required_env(name: String) -> Result[String, String] {
  match env.opt(name) {
    case Some(value) -> {
      let trimmed = value.trim

      if trimmed.size > 0 {
        Result.Ok(trimmed)
      } else {
        Result.Error('The environment variable ${name} is empty')
      }
    }
    case None -> Result.Error('The environment variable ${name} is missing')
  }
}

fn optional_env(name: String, fallback: String) -> String {
  match env.opt(name) {
    case Some(value) -> {
      let trimmed = value.trim

      if trimmed.size > 0 {
        trimmed
      } else {
        fallback
      }
    }
    case None -> fallback
  }
}

fn strip_trailing_slashes(value: String) -> String {
  let mut current = value

  loop {
    match current.strip_suffix('/') {
      case Some(val) -> current = val
      case None -> return current
    }
  }
}

fn read_stdin_to_string -> Result[String, String] {
  let bytes = ByteArray.new
  let mut reader = Stdin.new

  match reader.read_all(bytes) {
    case Ok(_) -> {
      if bytes.size > MAX_INPUT_BYTES {
        Result.Error('The stdin input is too large')
      } else {
        Result.Ok(bytes.drain_to_string)
      }
    }
    case Error(error) -> Result.Error('Failed to read stdin: ${error.to_string}')
  }
}

fn parse_json_string(text: String, label: String) -> Result[Json, String] {
  match Json.parse(Buffer.new(text)) {
    case Ok(json) -> Result.Ok(json)
    case Error(error) -> Result.Error('Failed to parse the ${label} as JSON: ${error.to_string}')
  }
}

fn validate_messages_input(input_json: String) -> Result[Json, String] {
  let json = try parse_json_string(input_json, 'input payload')

  match ref json {
    case Array(_) -> Result.Ok(json)
    case _ -> Result.Error('The input payload must be a JSON array of chat messages')
  }
}

fn error_message_from_body(body: String) -> String {
  match parse_json_string(body.clone, 'error response body') {
    case Ok(json) -> {
      match json.query.key('error_description').as_string {
        case Some(msg) -> { if msg.size > 0 { return msg } }
        case None -> {}
      }

      match json.query.key('message').as_string {
        case Some(msg) -> { if msg.size > 0 { return msg } }
        case None -> {}
      }

      match json.query.key('error').key('message').as_string {
        case Some(msg) -> { if msg.size > 0 { return msg } }
        case None -> {}
      }

      match json.query.key('error').as_string {
        case Some(msg) -> { if msg.size > 0 { return msg } }
        case None -> {}
      }

      body
    }
    case Error(_) -> body
  }
}

fn collect_output_content_text(item: ref Json, buffer: mut StringBuffer) {
  match item {
    case Object(object) -> {
      match object.opt('text') {
        case Some(value) -> collect_output_content_text(value, buffer)
        case None -> {}
      }

      match object.opt('value') {
        case Some(value) -> collect_output_content_text(value, buffer)
        case None -> {}
      }

      match object.opt('content') {
        case Some(value) -> collect_output_content_text(value, buffer)
        case None -> {}
      }
    }
    case Array(items) -> {
      let mut i = 0

      while i < items.size {
        match items.opt(i) {
          case Some(value) -> collect_output_content_text(value, buffer)
          case None -> {}
        }

        i += 1
      }
    }
    case String(value) -> {
      if value.size > 0 {
        buffer.push(value)
      }
    }
    case _ -> {}
  }
}

fn extract_text_from_value(value: ref Json) -> String {
  let buffer = StringBuffer.new

  collect_output_content_text(value, buffer)
  buffer.into_string
}

fn extract_output_from_object(object: ref Map[String, Json]) -> Result[String, String] {
  match object.opt('output_text') {
    case Some(value) -> {
      let text = extract_text_from_value(value)

      if text.size > 0 {
        return Result.Ok(text)
      }
    }
    case None -> {}
  }

  match object.opt('output') {
    case Some(value) -> {
      let text = extract_text_from_value(value)

      if text.size > 0 {
        Result.Ok(text)
      } else {
        Result.Error('No text output in response')
      }
    }
    case None -> Result.Error('No output_text in response')
  }
}

fn extract_output_text(body: String) -> Result[String, String] {
  let json = try parse_json_string(body, 'responses response')

  match json.query.key('output_text').as_string {
    case Some(text) -> {
      if text.size > 0 {
        Result.Ok(text)
      } else {
        match ref json {
          case Object(object) -> extract_output_from_object(object)
          case _ -> Result.Error('The responses response is not a JSON object')
        }
      }
    }
    case None -> {
      match ref json {
        case Object(object) -> extract_output_from_object(object)
        case _ -> Result.Error('The responses response is not a JSON object')
      }
    }
  }
}

fn build_responses_body(
  input_json: String,
  agent_id: String,
  max_tokens: Int,
) -> Result[String, String] {
  let input = try validate_messages_input(input_json)
  let mut root = Map.new

  root.set('model', Json.String(agent_id))
  root.set('input', input)
  root.set('max_output_tokens', Json.Int(max_tokens))

  Result.Ok(Json.Object(root).to_string)
}

fn call_azure_api(
  endpoint: String,
  api_key: String,
  body: String,
) -> Result[String, String] {
  let url = '${endpoint}/openai/v1/responses'
  let mut cmd = Command.new('curl')

  cmd.stdin = Stream.Piped
  cmd.stdout = Stream.Piped
  cmd.stderr = Stream.Inherit
  cmd.arguments = [
    '-s',
    '-X', 'POST',
    '-H', 'Content-Type: application/json',
    '-H', 'Accept: application/json',
    '-H', 'api-key: ${api_key}',
    '-d', '@-',
    url,
  ]

  let mut child = match cmd.spawn {
    case Ok(c) -> c
    case Error(e) -> return Result.Error('Failed to spawn curl: ${e.to_string}')
  }

  match child.stdin {
    case Some(mut s) -> {
      match s.write_string(body) {
        case Ok(_) -> {}
        case Error(e) -> return Result.Error('Failed to write to curl stdin: ${e.to_string}')
      }
    }
    case None -> {}
  }

  let output_bytes = ByteArray.new

  match child.stdout {
    case Some(mut s) -> {
      match s.read_all(output_bytes) {
        case Ok(_) -> {}
        case Error(e) -> return Result.Error('Failed to read curl stdout: ${e.to_string}')
      }
    }
    case None -> {}
  }

  match child.wait {
    case Ok(status) -> {
      if status.success?.false? {
        return Result.Error('curl exited with status ${status.to_int}')
      }
    }
    case Error(e) -> return Result.Error('Failed to wait for curl: ${e.to_string}')
  }

  let response_body = output_bytes.drain_to_string

  if response_body.size == 0 {
    return Result.Error('Empty response from API')
  }

  extract_output_text(response_body)
}

type async Main {
  fn async main {
    let mut stdout = Stdout.new
    let mut stderr = Stderr.new

    let input_json = match read_stdin_to_string {
      case Ok(value) -> value
      case Error(error) -> {
        let _ = stderr.print('Error: ${error}')
        let _ = stderr.flush
        return
      }
    }

    let api_key = match required_env('AZURE_API_KEY') {
      case Ok(value) -> value
      case Error(error) -> {
        let _ = stderr.print('Error: ${error}')
        let _ = stderr.flush
        return
      }
    }

    let endpoint = strip_trailing_slashes(
      optional_env('AZURE_EXISTING_AIPROJECT_ENDPOINT', DEFAULT_ENDPOINT)
    )
    let agent_id = optional_env('AZURE_EXISTING_AGENT_ID', DEFAULT_AGENT_ID)

    let body = match build_responses_body(input_json, agent_id, MAX_TOKENS) {
      case Ok(value) -> value
      case Error(error) -> {
        let _ = stderr.print('Error: ${error}')
        let _ = stderr.flush
        return
      }
    }

    match call_azure_api(endpoint, api_key, body) {
      case Ok(output_text) -> {
        let _ = stdout.print(output_text)
        let _ = stdout.flush
      }
      case Error(error) -> {
        let _ = stderr.print('Error: ${error}')
        let _ = stderr.flush
      }
    }
  }
}
